  const base62 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  const prefix = randomString(8, lowerAlnum, randomBytes);
  const secret = randomString(32, base62, randomBytes);
